struct  GPS_STRUCT
{
uint32_t itow_pos;
uint16_t week_num;
uint32_t pps_time_us; // mcu time when getting pps in microsecond
uint32_t revc_time_ms;
uint8_t fixtype;  // GNSSfix Type
uint8_t numSV;    // Number of satellites used in Nav Solution
uint8_t multiSVs; // Number of satellites with multi-frequency signals used in solution
double lat;//Latitude in deg
double lon;//Longitude in deg
int32_t alt;//Height above mean sea level in m*1e5
uint16_t p_hacc;//horrizon pos accuracy in mm
uint16_t p_vacc;//vertical pos accuracy in mm
uint16_t diff_age;
uint32_t itow_vel;
float vn;//NED north velocity in m/s
float ve;//NED east velocity in m/s
float vd;//NED down velocity in m/s
float gspeed;//Ground Speed (2-D) in m/s
float headMot;//Heading of motion (2-D) in deg
uint16_t v_hacc; // horizontal velocity accuracy mm/s
uint16_t v_vacc; // vertical velocity accuracy mm/s
}__attribute__((packed));

struct  IMU_STRUCT
{
uint32_t time_gps_ms;
uint16_t week_num;
float gyro[3];
float accel[3];
float temperature;
int16_t temp_vel;
uint8_t imu_type;//52-614P, 88-614B, 68-614P_PRO
uint8_t rtk_type;//0-um980,1-sinan k803
uint8_t zupt;
int16_t qekf_att[3];//roll,pitch,yaw   deg*100
int16_t kf_att[3];//roll,pitch,yaw   deg*100
}__attribute__((packed));

struct  KF_ONLINE
{
float pk[21];
float innov[6];
float att[3];
float vel[3];
double pos[3];
float gyro_bias[3];
float acceel_bias[3];
float gyro_scale[3];
float est_lever_arm[3];
uint32_t itow;
}__attribute__((packed));

